if (process.env.NODE_ENV === 'production') {
  const originalEmit = process.emit;
  process.emit = function(event, data) {
    if (event === 'warning' && data?.name === 'ExperimentalWarning') return false;
    return originalEmit.apply(process, arguments);
  };
}
